<script lang="ts">
  let {entity, connections=[]}=$props();
  let depth=$state(2); let showLabels=$state(true); let selected=$state<any>(null);
  const W=1000,H=620,cx=500,cy=310;
  const direct=$derived(connections.slice(0,24));
  const second=$derived.by(()=>{const seen=new Set<number>();const out:any[]=[];for(const c of direct){for(const edge of (c.graph_second_hop??[])){const other=Number(edge.subject_id)===Number(c.connected_id)?{id:Number(edge.object_id),name:edge.object_name,type:edge.object_type,rfx:edge.object_gets_rfx_entity_id,supplier:edge.object_gets_supplier_entity_id}:{id:Number(edge.subject_id),name:edge.subject_name,type:edge.subject_type,rfx:edge.subject_gets_rfx_entity_id,supplier:edge.subject_gets_supplier_entity_id};if(other.id===Number(entity.id))continue;const key=Number(edge.id);if(seen.has(key))continue;seen.add(key);out.push({edge,parent:Number(c.connected_id),...other});if(out.length>=60)return out;}}return out;});
  function parse(raw:any){try{return raw?JSON.parse(String(raw)):{};}catch{return {};}}
  function kindDirect(c:any){const m=parse(c.connected_metadata_json);if(c.connected_gets_rfx_entity_id)return 'tender';if(c.connected_gets_supplier_entity_id)return 'supplier';if(m?.gets?.kind==='agency')return 'agency';if(String(c.connected_slug??'').startsWith('charities-officer-'))return 'person';return String(c.connected_type||'other');}
  function kind2(n:any){if(n.rfx)return 'tender';if(n.supplier)return 'supplier';return String(n.type||'other');}
  function clean(name:any){return String(name||'Record').replace(/^Supplier record — /,'').replace(/ — RFx .*$/,'').replace(/^Procurement record RFx [^—]+ — /,'');}
  function fill(k:string){return k==='charity'?'#69c48d':k==='person'?'#73a9e6':k==='tender'?'#e5b65f':k==='supplier'?'#c58be2':k==='agency'||k==='public_agency'?'#62c8c3':k==='company'?'#ef8e78':'#9aa7a2';}
  function short(s:string,n=25){return s.length>n?s.slice(0,n-1)+'…':s;}
  function directPos(i:number,n:number){const a=(i/Math.max(n,1))*Math.PI*2-Math.PI/2;return{x:cx+Math.cos(a)*230,y:cy+Math.sin(a)*175};}
  function secondPos(i:number,n:number){const a=(i/Math.max(n,1))*Math.PI*2-Math.PI/2+.06;return{x:cx+Math.cos(a)*425,y:cy+Math.sin(a)*270};}
  function dpos(id:number){const i=direct.findIndex((c:any)=>Number(c.connected_id)===id);return directPos(Math.max(i,0),direct.length);}
  function selectSecond(n:any,k:string){selected={id:n.id,name:n.name,predicate:n.edge.predicate,kind:k,source:n.edge};}
  function selectDirect(c:any,k:string){selected={id:c.connected_id,name:c.connected_name,predicate:c.predicate,kind:k,source:c};}
  function keySecond(e:KeyboardEvent,n:any,k:string){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectSecond(n,k);}}
  function keyDirect(e:KeyboardEvent,c:any,k:string){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectDirect(c,k);}}
</script>
<section class="graph-section">
  <div class="graph-head"><div><p class="eyebrow">Relationship explorer</p><h2>Graph view</h2></div><div class="view-note">{direct.length} direct · {second.length} second-hop connections shown</div></div>
  <div class="graph-shell">
    <aside class="legend"><strong>Legend</strong><span><i style="background:#69c48d"></i>Charity</span><span><i style="background:#73a9e6"></i>Officer / person</span><span><i style="background:#e5b65f"></i>Government tender</span><span><i style="background:#c58be2"></i>GETS supplier</span><span><i style="background:#62c8c3"></i>Government agency</span><span><i style="background:#ef8e78"></i>Company</span></aside>
    <div class="canvas">
      {#if connections.length===0}<div class="graph-empty">No connections are currently loaded for this record.</div>{:else}
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`Relationship graph for ${entity.canonical_name}`}>
        {#if depth===2}{#each second as n,i}{@const a=dpos(n.parent)}{@const b=secondPos(i,second.length)}<line class="second-edge" x1={a.x} y1={a.y} x2={b.x} y2={b.y}/>{/each}{/if}
        {#each direct as c,i}{@const p=directPos(i,direct.length)}<line class="direct-edge" x1={cx} y1={cy} x2={p.x} y2={p.y}/>{/each}
        {#if depth===2}{#each second as n,i}{@const p=secondPos(i,second.length)}{@const k=kind2(n)}<g class="node secondary" role="link" tabindex="0" onclick={()=>selectSecond(n,k)} onkeydown={(e)=>keySecond(e,n,k)}><circle cx={p.x} cy={p.y} r="8" fill={fill(k)}/>{#if showLabels}<text x={p.x} y={p.y+21} text-anchor="middle">{short(clean(n.name),20)}</text>{/if}</g>{/each}{/if}
        {#each direct as c,i}{@const p=directPos(i,direct.length)}{@const k=kindDirect(c)}<g class="node" role="link" tabindex="0" onclick={()=>selectDirect(c,k)} onkeydown={(e)=>keyDirect(e,c,k)}><circle cx={p.x} cy={p.y} r="11" fill={fill(k)}/>{#if showLabels}<text x={p.x} y={p.y+25} text-anchor="middle">{short(clean(c.connected_name))}</text>{/if}</g>{/each}
        <g class="center"><circle cx={cx} cy={cy} r="22"/><circle cx={cx} cy={cy} r="30" class="halo"/><text x={cx} y={cy+48} text-anchor="middle">{short(entity.canonical_name,38)}</text></g>
      </svg>{/if}
    </div>
    <aside class="controls"><strong>View</strong><label><span>Depth</span><select bind:value={depth}><option value={1}>1 hop</option><option value={2}>2 hops</option></select></label><label class="check"><input type="checkbox" bind:checked={showLabels}/> Labels</label><p>Depth 2 follows evidence-backed relationships one additional step from the records directly connected to this page.</p><p class="cap">Preview caps: 24 direct nodes and 60 second-hop edges.</p></aside>
  </div>
  {#if selected}<div class="selection"><div><small>Selected connection</small><strong>{clean(selected.name)}</strong><span>{String(selected.predicate).replaceAll('_',' ')} · {selected.kind}</span>{#if selected.source?.publisher}<small>Evidence: {selected.source.publisher} · {selected.source.dataset}</small>{/if}</div><a href={`/record/${selected.id}`}>Open record →</a><button onclick={()=>selected=null} aria-label="Close selection">×</button></div>{/if}
  <p class="graph-disclaimer"><strong>What does a connection mean?</strong> Lines show relationships found in public records. A connection does not by itself imply wrongdoing, influence or endorsement. Check the record's source evidence for context.</p>
</section>
<style>
.graph-section{margin-top:38px}.graph-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.graph-head h2{font-family:Georgia,'Times New Roman',serif;font-size:30px;margin:2px 0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#176b5a;font-weight:700;margin:0}.view-note{font-size:12px;color:#68726e}.graph-shell{position:relative;display:grid;grid-template-columns:155px minmax(0,1fr) 170px;min-height:620px;background:#111817;border:1px solid #293532;overflow:hidden}.canvas{position:relative;min-width:0;background:radial-gradient(circle at 50% 50%,#1c2a27 0,#111817 58%,#0c1211 100%);border-left:1px solid #293532;border-right:1px solid #293532}.canvas:before{content:'';position:absolute;inset:0;background-image:radial-gradient(#40514d 1px,transparent 1px);background-size:24px 24px;opacity:.22}.canvas svg{position:relative;width:100%;height:620px;display:block}.canvas line{stroke:#5d706b;stroke-width:1;opacity:.6}.canvas .second-edge{opacity:.38;stroke:#71817c}.canvas .direct-edge{stroke-width:1.3}.canvas text{fill:#dfe9e5;font:11px Arial,Helvetica,sans-serif;paint-order:stroke;stroke:#111817;stroke-width:4px;stroke-linejoin:round}.node{cursor:pointer}.node circle{stroke:#e7efec;stroke-width:1.5}.node.secondary circle{stroke-width:1}.node:hover circle{stroke-width:4}.center circle:first-child{fill:#3da978;stroke:#dff7eb;stroke-width:2}.center .halo{fill:none;stroke:#3da978;stroke-width:2;opacity:.28}.center text{font-weight:700;font-size:14px}.legend,.controls{z-index:2;color:#cbd8d3;padding:18px 14px;font-size:11px;background:#101715}.legend strong,.controls strong{display:block;color:#fff;text-transform:uppercase;letter-spacing:.08em;font-size:10px;margin-bottom:16px}.legend span{display:flex;align-items:center;gap:8px;margin:10px 0}.legend i{width:9px;height:9px;border-radius:50%;display:inline-block}.controls label{display:flex;flex-direction:column;gap:6px;margin:12px 0;color:#9eada8}.controls select{background:#192320;border:1px solid #34433f;color:#dce7e3;padding:7px}.controls .check{flex-direction:row;align-items:center}.controls p{line-height:1.5;color:#82918c;margin-top:20px}.controls .cap{font-size:10px;color:#66746f}.graph-empty{position:absolute;inset:0;display:grid;place-items:center;color:#93a19c;font-size:13px}.selection{display:flex;align-items:center;gap:18px;background:#fff;border:1px solid #d5dad6;border-top:0;padding:14px 18px}.selection div{display:flex;flex-direction:column;gap:3px;flex:1}.selection small,.selection span{font-size:11px;color:#68726e}.selection a{font-weight:700;font-size:13px}.selection button{border:0;background:none;font-size:24px;color:#68726e;cursor:pointer}.graph-disclaimer{font-size:12px;line-height:1.5;color:#59635f;margin:12px 0 0}.graph-disclaimer strong{color:#202624;margin-right:4px}@media(max-width:800px){.graph-shell{grid-template-columns:1fr;min-height:auto}.legend,.controls{display:none}.canvas{border:0}.canvas svg{height:500px}.view-note{display:none}}@media(max-width:520px){.canvas svg{height:420px}.selection{align-items:flex-start;flex-wrap:wrap}}
</style>